//! The `bsc memory` command surface. Thin: arg-parsing here, persistence in `bsc-json-store`, and the
//! decisions (tag/link parsing, ordering, filtering) in the crate root where they are tested.

use crate::{filter_and_order, is_kind, parse_link_specs, parse_tags, Filter, Link, Memory, HORIZON_FUTURE, HORIZON_NOW, KINDS, KIND_NOTE};
use bsc_cli_util::CmdDoc;
use bsc_json_store::Store;
use std::time::{SystemTime, UNIX_EPOCH};

/// One-line-per-command overview, consumed by `bsc memory` (and the top-level `bsc` help).
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "add",
        summary: "capture a lesson / highlight / record note / ambient thought (--kind, --future for an idea)",
        usage: "USAGE:\n  bsc memory add \"<text>\" [--kind lesson|highlight|record|ambient|note] [--tag a,b] [--link rel:ref,rel:ref] [--future | --horizon now|future] [--dir <store>]\n\nRecords one memory and prints it.\n\n--kind says what SORT of memory this is, and the kinds are not interchangeable:\n  lesson     what we got wrong, and the rule that came out of it\n  highlight  a discussion or decision that should persist indefinitely\n  record     a comment explaining why a code record is the way it is\n  ambient    what the always-on ear caught, awaiting promotion\n  note       not yet classified (the DEFAULT - omitting --kind never mislabels)\nAn unknown kind is REFUSED rather than stored: a typo would be a memory that appears under no tab.\n\n--link edges are typed `rel:ref` (bare ref => `related`). A target may carry an explicit node-type\nprefix - `about:feature:auth`, `about:session:studio-code:director` - because a feature slug and a\nplan ref are the same SHAPE and nothing can tell them apart without being told.\n\n--future marks a forward-looking idea rather than something applicable to what is implemented.",
    },
    CmdDoc {
        name: "list",
        summary: "list memories, newest first (--kind / --tag / --status / --link / --rel / --horizon / --json)",
        usage: "USAGE:\n  bsc memory list [--kind <k>] [--tag <t>] [--status open|done] [--link <ref>] [--rel <rel>] [--horizon now|future] [--json] [--dir <store>]\n\n--link is the BACK-REFERENCE query: `--link <record-id>` answers \"what do we remember about this?\" for any node - a record, a plan ref, a feature, a session.",
    },
    CmdDoc { name: "get", summary: "print one memory by id", usage: "USAGE:\n  bsc memory get <id> [--dir <store>]" },
    CmdDoc {
        name: "link",
        summary: "add a typed edge: connect a memory to related refs under one relationship",
        usage: "USAGE:\n  bsc memory link <id> <rel> <ref> [<ref>...] [--dir <store>]\n\nAdds edges `<rel>` from <id> to each <ref> (a memory id, a graph record id, a symbol anchor, a plan ref). De-duplicated by (rel, ref). Common rels: about · because · supersedes · contradicts · lesson-of · blocks · todo-for.",
    },
    CmdDoc {
        name: "neighbors",
        summary: "traverse: the typed edges out of a memory, and the ones that point back to it",
        usage: "USAGE:\n  bsc memory neighbors <id> [--json] [--dir <store>]",
    },
    CmdDoc {
        name: "horizon",
