fn now_ms() -> i64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as i64).unwrap_or(0)
}
fn new_id() -> String {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos().to_string()).unwrap_or_else(|_| "0".into())
}

fn flag<'a>(args: &'a [String], name: &str) -> Option<&'a str> {
    args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).map(String::as_str)
}
fn has_flag(args: &[String], name: &str) -> bool {
    args.iter().any(|a| a == name)
}

/// The store, pointed at `--dir` when given (tests use a temp dir) or the base dir otherwise.
fn open(args: &[String]) -> Store {
    let dir = flag(args, "--dir")
        .map(std::path::PathBuf::from)
        .or_else(bsc_util::bsc_base_dir)
        .unwrap_or_else(|| std::path::PathBuf::from("."));
    Store::new(dir, "memory")
}

/// The flags that TAKE a value — their following token is consumed, never a positional.
const VALUE_FLAGS: &[&str] = &["--tag", "--status", "--dir", "--link", "--rel", "--horizon", "--kind"];

/// Positional args — everything that is neither a flag nor a flag's value.
fn positionals(args: &[String]) -> Vec<&str> {
    let mut out = Vec::new();
    let mut skip = false;
    for a in args {
        if skip {
            skip = false;
            continue;
        }
        if VALUE_FLAGS.contains(&a.as_str()) {
            skip = true;
            continue;
        }
        if a.starts_with("--") {
            continue;
        }
        out.push(a.as_str());
    }
    out
}

/// The kind a memory is being captured as. REFUSES an unknown value rather than storing it: a typo'd
/// kind is a memory that appears under no reading surface at all, which is worse than being made to
/// retype the flag.
fn kind_of(args: &[String], prog: &str) -> Result<String, String> {
    match flag(args, "--kind") {
        None => Ok(KIND_NOTE.to_string()),
        Some(k) if is_kind(k) => Ok(k.trim().to_lowercase()),
        Some(k) => Err(format!("{prog}: unknown kind '{k}' - one of: {}", KINDS.join(" | "))),
    }
}

/// The horizon a memory is being captured on: `--future` (or `--horizon future`) => future, else now.
fn horizon_of(args: &[String]) -> String {
    if has_flag(args, "--future") {
        return HORIZON_FUTURE.to_string();
    }
    match flag(args, "--horizon") {
        Some(h) if h.eq_ignore_ascii_case(HORIZON_FUTURE) => HORIZON_FUTURE.to_string(),
        _ => HORIZON_NOW.to_string(),
    }
}

/// Every stored memory. `Store::list()` yields the verbatim JSON BODIES (ordered by id), not ids — so
/// parse each one directly. (Feeding a body back into `store.get` would slugify the blob and find nothing.)
fn all(store: &Store) -> Result<Vec<Memory>, String> {
    let mut v = Vec::new();
    for raw in store.list() {
        if let Ok(m) = serde_json::from_str::<Memory>(&raw) {
            v.push(m);
        }
    }
    Ok(v)
}

fn load(store: &Store, id: &str) -> Result<Memory, String> {
    let raw = store.get(id)?.ok_or_else(|| format!("no memory '{id}'"))?;
    serde_json::from_str(&raw).map_err(|e| e.to_string())
}

fn save(store: &Store, m: &Memory) -> Result<(), String> {
    store.set(&m.id, &serde_json::to_string(m).map_err(|e| e.to_string())?)
}

/// Dispatch. `prog` is the invoked name (`bsc memory`) for error/usage text.
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    match args.first().map(String::as_str).unwrap_or("") {
        "add" => add(&args[1..], prog),
        "list" => list(&args[1..]),
        "get" => get(&args[1..], prog),
        "link" => link(&args[1..], prog),
        "neighbors" => neighbors(&args[1..], prog),
        "horizon" => horizon(&args[1..], prog),
        "kind" => kind(&args[1..], prog),
        "brief" => brief_cmd(&args[1..], prog),
        "done" => done(&args[1..], prog),
        "" | "help" | "-h" | "--help" => {
            print_help(prog);
            Ok(())
        }
        other => Err(format!("{prog}: unknown command '{other}' — try `{prog} help`")),
    }
}

fn add(args: &[String], prog: &str) -> Result<(), String> {
    let text = positionals(args).join(" ");
    if text.trim().is_empty() {
        return Err(format!("usage: {prog} add \"<text>\" [--tag a,b] [--link rel:ref] [--future]"));
    }
    let tags = flag(args, "--tag").map(parse_tags).unwrap_or_default();
    let links = flag(args, "--link").map(parse_link_specs).unwrap_or_default();
    let memory = Memory {
        id: new_id(),
        text: text.trim().to_string(),
        tags,
        created_at_ms: now_ms(),
        status: "open".into(),
        horizon: horizon_of(args),
        kind: kind_of(args, prog)?,
        links,
    };
    let store = open(args);
    save(&store, &memory)?;
    println!("{}", serde_json::to_string(&memory).map_err(|e| e.to_string())?);
    Ok(())
}

fn list(args: &[String]) -> Result<(), String> {
    let store = open(args);
    let items = all(&store)?;
    let f = Filter {
        tag: flag(args, "--tag"),
        status: flag(args, "--status"),
        link: flag(args, "--link"),
        rel: flag(args, "--rel"),
        horizon: flag(args, "--horizon"),
        kind: flag(args, "--kind"),
    };
    let out = filter_and_order(&items, &f);
    if has_flag(args, "--json") {
        println!("{}", serde_json::to_string(&out).map_err(|e| e.to_string())?);
    } else {
        for m in &out {
            let tags = if m.tags.is_empty() { String::new() } else { format!("  [{}]", m.tags.join(",")) };
            let links = if m.links.is_empty() { String::new() } else { format!("  ->{}", m.links.len()) };
            let horizon = if m.horizon == crate::HORIZON_FUTURE { "  ~future" } else { "" };
            // The kind leads the line: it is what decides whether this memory is even the sort of
            // thing you are looking for, and `note` prints too because unclassified is a state to act
            // on, not an absence to hide.
            let kind = format!("  {:<9}", m.kind);
            let mark = if m.status == "done" { "done" } else { "open" };
            println!("{mark}{kind}  {}{tags}{links}{horizon}  {}", &m.id[..m.id.len().min(10)], m.text);
        }
    }
    Ok(())
}

fn get(args: &[String], prog: &str) -> Result<(), String> {
    let id = positionals(args).first().copied().ok_or_else(|| format!("usage: {prog} get <id>"))?;
    match open(args).get(id)? {
        Some(raw) => {
            println!("{raw}");
            Ok(())
        }
        None => Err(format!("{prog}: no memory '{id}'")),
    }
}

fn link(args: &[String], prog: &str) -> Result<(), String> {
    let pos = positionals(args);
    // <id> <rel> <ref> [<ref>...]
    let id = pos.first().copied().ok_or_else(|| format!("usage: {prog} link <id> <rel> <ref> [<ref>...]"))?;
    let rel = pos.get(1).copied().ok_or_else(|| format!("usage: {prog} link <id> <rel> <ref> [<ref>...]"))?;
    let refs = &pos[2.min(pos.len())..];
    if refs.is_empty() {
        return Err(format!("usage: {prog} link <id> <rel> <ref> [<ref>...]"));
    }
    let rel = rel.trim().to_lowercase();
    let store = open(args);
    let mut memory = load(&store, id).map_err(|e| format!("{prog}: {e}"))?;
    for r in refs {
        let target = r.trim().to_string();
        if target.is_empty() {
            continue;
        }
        if !memory.links.iter().any(|l| l.target == target && l.rel == rel) {
            memory.links.push(Link::new(target, rel.clone()));
        }
    }
    save(&store, &memory)?;
    let rendered: Vec<String> = memory.links.iter().map(|l| format!("{}:{}", l.rel, l.target)).collect();
    println!("{id} -> [{}]", rendered.join(", "));
    Ok(())
}

fn neighbors(args: &[String], prog: &str) -> Result<(), String> {
    let id = positionals(args).first().copied().ok_or_else(|| format!("usage: {prog} neighbors <id>"))?;
    let store = open(args);
    let items = all(&store)?;
    // The memory must exist, so a typo is an error rather than a silent empty traversal.
    let me = items.iter().find(|m| m.id == id).ok_or_else(|| format!("{prog}: no memory '{id}'"))?;
    let outgoing: Vec<(&str, &str)> = me.links.iter().map(|l| (l.rel.as_str(), l.target.as_str())).collect();
    // Incoming: any OTHER memory carrying a link whose target is this id, with the rel it used.
    let incoming: Vec<(&str, &str)> = items
        .iter()
        .filter(|m| m.id != id)
        .flat_map(|m| m.links.iter().filter(|l| l.target == id).map(move |l| (l.rel.as_str(), m.id.as_str())))
        .collect();
    if has_flag(args, "--json") {
        let out: Vec<_> = outgoing.iter().map(|(rel, r)| serde_json::json!({ "rel": rel, "ref": r })).collect();
        let inc: Vec<_> = incoming.iter().map(|(rel, r)| serde_json::json!({ "rel": rel, "ref": r })).collect();
        let v = serde_json::json!({ "id": id, "outgoing": out, "incoming": inc });
        println!("{}", serde_json::to_string(&v).map_err(|e| e.to_string())?);
    } else {
        println!("{id}");
        if outgoing.is_empty() {
            println!("  -> (none)");
        } else {
            for (rel, r) in &outgoing {
                println!("  -{rel}-> {r}");
            }
        }
        if incoming.is_empty() {
            println!("  <- (none)");
        } else {
            for (rel, r) in &incoming {
                println!("  <-{rel}- {r}");
            }
        }
    }
    Ok(())
}

fn horizon(args: &[String], prog: &str) -> Result<(), String> {
    let pos = positionals(args);
    let id = pos.first().copied().ok_or_else(|| format!("usage: {prog} horizon <id> now|future"))?;
    let want = pos.get(1).copied().ok_or_else(|| format!("usage: {prog} horizon <id> now|future"))?;
    let h = match want.to_lowercase().as_str() {
        HORIZON_NOW => HORIZON_NOW,
        HORIZON_FUTURE => HORIZON_FUTURE,
        _ => return Err(format!("{prog}: horizon must be `now` or `future`, not '{want}'")),
    };
    let store = open(args);
    let mut memory = load(&store, id).map_err(|e| format!("{prog}: {e}"))?;
    memory.horizon = h.to_string();
    save(&store, &memory)?;
    println!("{id} -> {h}");
    Ok(())
}

fn kind(args: &[String], prog: &str) -> Result<(), String> {
    let pos = positionals(args);
    let usage = || format!("usage: {prog} kind <id> {}", KINDS.join("|"));
    let id = pos.first().copied().ok_or_else(usage)?;
    let want = pos.get(1).copied().ok_or_else(usage)?;
    if !is_kind(want) {
        return Err(format!("{prog}: unknown kind '{want}' - one of: {}", KINDS.join(" | ")));
    }
    let k = want.trim().to_lowercase();
    let store = open(args);
    let mut memory = load(&store, id).map_err(|e| format!("{prog}: {e}"))?;
    memory.kind = k.clone();
    save(&store, &memory)?;
    println!("{id} -> {k}");
    Ok(())
}

/// `bsc memory brief <ref>...` — the block a launching session receives. The refs are the nodes it
/// will touch: the records its feature requires, its stream id, its feature slug, its plan ref.
fn brief_cmd(args: &[String], prog: &str) -> Result<(), String> {
    let refs: Vec<String> = positionals(args).iter().map(|s| (*s).to_string()).collect();
    if refs.is_empty() {
        return Err(format!("usage: {prog} brief <ref> [<ref>...]"));
    }
    let items = all(&open(args))?;
    let b = crate::brief::brief(&items, &refs);
    if has_flag(args, "--json") {
        let out = serde_json::json!({
            "aboutThisWork": b.about_this_work,
            "standing": b.standing,
            "recordNotes": b.record_notes,
            "notShown": b.not_shown,
            "command": crate::brief::command(&refs),
        });
        println!("{}", serde_json::to_string(&out).map_err(|e| e.to_string())?);
    } else {
        print!("{}", crate::brief::render(&b, &refs));
    }
    Ok(())
}

fn done(args: &[String], prog: &str) -> Result<(), String> {
    let id = positionals(args).first().copied().ok_or_else(|| format!("usage: {prog} done <id>"))?;
    let store = open(args);
    let mut memory = load(&store, id).map_err(|e| format!("{prog}: {e}"))?;
    memory.status = "done".into();
    save(&store, &memory)?;
    println!("{id} -> done");
    Ok(())
}

fn print_help(prog: &str) {
    println!("{prog} — capture what a session learns as a typed graph, so it doesn't go to the void\n");
    for c in COMMANDS {
        println!("  {:9} {}", c.name, c.summary);
    }
    println!("\nMemories live in ~/.base-studio-code/memory.db (override with --dir).");
    println!("A memory has a horizon (now = applies to what is implemented, future = an idea) and typed");
    println!("links {{ref, rel}} you traverse with `neighbors`.");
}
